WITH store_summary AS (SELECT store_id, COUNT(*) AS total_count, MAX(quantity) - MIN(quantity) AS quantity_range FROM inventory GROUP BY store_id) SELECT stores.city, stores.store_name, store_summary.total_count, store_summary.quantity_range FROM stores INNER JOIN store_summary ON stores.id = store_summary.store_id WHERE store_summary.total_count >= 8 ORDER BY store_summary.total_count DESC, city
